import assert from 'node:assert/strict';
import { LabelService } from './service.mjs';
import { Cache, Database } from './model.mjs';

const checks = [];
const check = (name, run) => checks.push({ name, run });
function setup() {
  const database = new Database([
    { id: 'north', label: 'Original', revision: 1 },
    { id: 'south', label: 'Separate', revision: 1 },
  ]);
  const cache = new Cache();
  return { database, cache, a: new LabelService(database, cache), b: new LabelService(database, cache) };
}

check('a delayed fill cannot regress reads started after a completed write', async () => {
  const { database, a, b } = setup();
  const gate = database.pauseNextRead();
  const overlappingRead = a.read('north');
  await gate.captured;
  const committed = await b.write('north', 'Revised');
  gate.release();
  await overlappingRead; // This read overlaps the write; either snapshot is permitted.
  assert.deepEqual(await b.read('north'), committed);
});

check('evicting a cached value does not allow an older delayed fill to return', async () => {
  const { database, cache, a, b } = setup();
  const gate = database.pauseNextRead();
  const overlappingRead = a.read('north');
  await gate.captured;
  const committed = await b.write('north', 'Revised');
  await b.read('north');
  await cache.evict('north');
  gate.release();
  await overlappingRead;
  assert.deepEqual(await b.read('north'), committed);
});

check('a delayed earlier write notification cannot erase knowledge of a newer revision', async () => {
  const { database, cache, a, b } = setup();
  const gate = database.pauseNextRead();
  const overlappingRead = a.read('north');
  await gate.captured;
  await b.write('north', 'Second');
  const committed = await b.write('north', 'Third');
  await cache.advanceFloor('north', 2);
  await cache.evict('north');
  gate.release();
  await overlappingRead;
  assert.deepEqual(await b.read('north'), committed);
});

check('a populated cache serves repeated reads without extra database reads', async () => {
  const { database, a, b } = setup();
  const first = await a.read('north');
  assert.deepEqual(await b.read('north'), first);
  assert.equal(database.readCount, 1);
});

check('a write to another account leaves a populated entry usable', async () => {
  const { database, a, b } = setup();
  const first = await a.read('north');
  await b.write('south', 'Another');
  assert.deepEqual(await b.read('north'), first);
  assert.equal(database.readCount, 1);
});

let failures = 0;
for (const { name, run } of checks) {
  try {
    await run();
    console.log(`PASS ${name}`);
  } catch (error) {
    failures++;
    console.error(`FAIL ${name}\n${error.stack}`);
  }
}
console.log(`${checks.length - failures}/${checks.length} checks passed`);
process.exitCode = failures ? 1 : 0;

# Account label cache

Two `LabelService` instances share the supplied database and cache adapters. A
database row has an immutable ID and a monotonically increasing integer
`revision`; every write increments that revision. Database reads capture the
row at invocation and may complete later. The database is authoritative.

Once `write(id, label)` resolves with revision R, a read invoked afterwards must
return revision R or newer. A read already running when the write occurs may
return its earlier snapshot. A completed older read must not cause subsequent
reads to regress. Repeated reads of a populated cache must avoid database reads.
Different IDs are independent. Keep the public `read` and `write` signatures.

`model.mjs` supplies these adapter contracts:

- `database.read(id)` and `database.write(id, label)` return detached records.
- `cache.get(id)`, `cache.set(id, record)`, and `cache.delete(id)` operate on
  evictable cached values. `set` unconditionally replaces the current value.
- `cache.advanceFloor(id, revision)` atomically raises a shared revision floor,
  never lowers it, and removes a value older than the resulting floor.
- `cache.publishIfFresh(id, record)` atomically rejects a record older than
  either the floor or the current cached value, returning `false`; otherwise it
  stores the record, raises the floor if needed, and returns `true`.
- `cache.evict(id)` removes the cached value. Revision floors are stored
  separately and survive this operation. This fixture assumes floors outlive
  every outstanding reader and all instances use the same floor store.

Edit only `service.mjs`. Run `node verify.mjs`; no installation is needed.
The supplied checks control asynchronous ordering without wall-clock sleeps.
This exercise covers successful adapter calls and overlapping operations.
Crashes between the database commit and cache update, unavailable adapters,
floor expiry, replica reads, and production storage implementations are outside
the supplied model. Passing these checks does not establish a distributed
transaction between a real database and a real cache.
export class LabelService {
  constructor(database, cache) {
    this.database = database;
    this.cache = cache;
  }

  async read(id) {
    const cached = await this.cache.get(id);
    if (cached) return cached;
    const record = await this.database.read(id);
    await this.cache.set(id, record);
    return record;
  }

  async write(id, label) {
    const record = await this.database.write(id, label);
    await this.cache.delete(id);
    return record;
  }
}

const copy = value => value === undefined ? undefined : structuredClone(value);

export function deferred() {
  let resolve;
  const promise = new Promise(done => { resolve = done; });
  return { promise, resolve };
}

export class Database {
  constructor(records) {
    this.records = new Map(records.map(record => [record.id, copy(record)]));
    this.readCount = 0;
    this.nextReadGate = undefined;
  }

  pauseNextRead() {
    const captured = deferred();
    const resume = deferred();
    this.nextReadGate = { captured, resume };
    return { captured: captured.promise, release: () => resume.resolve() };
  }

  async read(id) {
    this.readCount++;
    const record = copy(this.records.get(id));
    if (!record) throw new Error(`Unknown account: ${id}`);
    const gate = this.nextReadGate;
    this.nextReadGate = undefined;
    if (gate) {
      gate.captured.resolve();
      await gate.resume.promise;
    }
    return record;
  }

  async write(id, label) {
    const previous = this.records.get(id);
    if (!previous) throw new Error(`Unknown account: ${id}`);
    const record = { id, label, revision: previous.revision + 1 };
    this.records.set(id, record);
    return copy(record);
  }
}

export class Cache {
  constructor() {
    this.values = new Map();
    this.floors = new Map();
  }

  async get(id) { return copy(this.values.get(id)); }
  async set(id, record) { this.values.set(id, copy(record)); }
  async delete(id) { this.values.delete(id); }
  async evict(id) { this.values.delete(id); }

  async advanceFloor(id, revision) {
    const floor = Math.max(this.floors.get(id) ?? 0, revision);
    this.floors.set(id, floor);
    if ((this.values.get(id)?.revision ?? Infinity) < floor) this.values.delete(id);
  }

  async publishIfFresh(id, record) {
    const floor = Math.max(this.floors.get(id) ?? 0, this.values.get(id)?.revision ?? 0);
    if (record.revision < floor) return false;
    this.floors.set(id, record.revision);
    this.values.set(id, copy(record));
    return true;
  }
}
